namespace Serenity.CodeGeneration;

public class TextKeysWriterTests
{
    private static string Write(params string[] keys)
    {
        var result = TextKeysWriter.Write(keys);
        Assert.Empty(result.Diagnostics);
        return result.Source.Replace("\r\n", "\n");
    }

    [Fact]
    public void Keeps_The_Segments_Of_The_Keys_As_They_Are()
    {
        Assert.Equal(
            """
            // <auto-generated />

            /// <summary>The local text keys of the project, a constant for each of their segments.</summary>
            public static partial class TextKeys
            {
                /// <summary>The text keys under "Db".</summary>
                public static partial class Db
                {
                    /// <summary>The text keys under "Db.Northwind".</summary>
                    public static partial class Northwind
                    {
                        /// <summary>The text keys under "Db.Northwind.Customer".</summary>
                        public static partial class Customer
                        {
                            /// <summary>""</summary>
                            public const string Fax = "Db.Northwind.Customer.Fax";
                            /// <summary>""</summary>
                            public const string Fax_Placeholder = "Db.Northwind.Customer.Fax_Placeholder";
                        }
                    }
                }
            }
            """.Replace("\r\n", "\n"),
            Write("Db.Northwind.Customer.Fax", "Db.Northwind.Customer.Fax_Placeholder"));
    }

    [Fact]
    public void Puts_The_Keys_Of_A_Class_In_The_Order_Of_Their_Names()
    {
        var source = Write("Db.B", "Db.A", "Db.Z.Y", "Db.Z.X");
        Assert.Contains("public const string A = \"Db.A\";", source);
        Assert.True(source.IndexOf("public const string A = ") < source.IndexOf("public const string B = "));
        Assert.True(source.IndexOf("public const string X = ") < source.IndexOf("public const string Y = "));
    }

    [Fact]
    public void Writes_The_Namespace_Of_The_Constants()
    {
        var source = TextKeysWriter.Write(["Db.A"], "Serenity.Demo").Source.Replace("\r\n", "\n");
        Assert.Contains("namespace Serenity.Demo\n{\n    /// <summary>The local text", source);
        Assert.Contains("    public static partial class TextKeys", source);
    }

    [Fact]
    public void Writes_Nothing_For_No_Keys()
    {
        var result = TextKeysWriter.Write([]);
        Assert.Empty(result.Source);
        Assert.Empty(result.Diagnostics);
        Assert.False(result.HasDiagnostics);
    }

    [Fact]
    public void With_Custom_Class_Name()
    {
        var source = TextKeysWriter.Write(["Db.A"], className: "Keys").Source;
        Assert.Contains("public static partial class Keys", source);
        Assert.DoesNotContain("class TextKeys", source);
    }

    [Fact]
    public void Capitalizes_The_First_Letter_Of_A_Segment()
    {
        var source = Write("Db.Northwind.Customer.fax");
        Assert.Contains("public const string Fax = \"Db.Northwind.Customer.fax\";", source);
    }

    [Fact]
    public void Writes_Both_Of_Two_Keys_That_Differ_Only_In_Case()
    {
        // the keys are case sensitive, so the one that differs only in case keeps the name that it has
        var source = Write("Db.Northwind.Customer.Fax", "Db.Northwind.Customer.fax");
        Assert.Contains("public const string Fax = \"Db.Northwind.Customer.Fax\";", source);
        Assert.Contains("public const string fax = \"Db.Northwind.Customer.fax\";", source);
        Assert.DoesNotContain("Not written", source);
    }

    [Fact]
    public void Tells_The_Invariant_Text_Of_A_Key_In_The_Summary_Of_Its_Constant()
    {
        var source = TextKeysWriter.Write(["Db.Northwind.Customer.Fax", "Db.Northwind.Customer.City"],
            texts: new Dictionary<string, string?>
            {
                ["Db.Northwind.Customer.Fax"] = "Fax",
                ["Db.Northwind.Customer.City"] = "City & <Town>" // a text that the docs need to escape
            }).Source.Replace("\r\n", "\n");

        // the summary is the text itself, as the name of the constant says which key it is
        Assert.Contains("/// <summary>City &amp; &lt;Town&gt;</summary>", source);
        Assert.Contains("public const string City = \"Db.Northwind.Customer.City\";", source);
        Assert.Contains("/// <summary>Fax</summary>", source);
    }

    [Fact]
    public void Summarizes_A_Key_That_Has_No_Text_With_An_Empty_One()
    {
        var source = TextKeysWriter.Write(["Db.A.B", "Db.A.C", "Db.A.D"], texts: new Dictionary<string, string?>
        {
            ["Db.A.B"] = "  ",
            ["Db.A.C"] = "",
            ["Db.A.D"] = "First line\r\nsecond line"
        }).Source;

        var empty = "/// <summary>\"\"</summary>";
        Assert.Equal(2, source.Replace("\r\n", "\n").Split(empty).Length - 1);
        // a text of more than one line is written on one, as the other lines would break the comment
        Assert.Contains("/// <summary>First line second line</summary>", source);
    }

    [Fact]
    public void Summarizes_A_Key_That_Its_Texts_Do_Not_Have_With_An_Empty_One()
    {
        var source = TextKeysWriter.Write(["Db.A.B"], texts: new Dictionary<string, string?>
        {
            ["Db.A.C"] = "See"
        }).Source;

        Assert.Contains("/// <summary>\"\"</summary>", source);
    }

    [Fact]
    public void Escapes_A_Segment_That_Is_A_Keyword()
    {
        // a segment that is a keyword gets its first letter capitalized instead, which no longer makes it one
        var source = Write("Db.class.Value");
        Assert.Contains("public static partial class Class", source);
        Assert.Contains("public const string Value = \"Db.class.Value\";", source);
    }

    [Fact]
    public void Mangles_A_Segment_That_Is_Not_An_Identifier()
    {
        var source = Write("Db.Northwind.Customer.Fax No", "Db.Northwind.Customer.2Days");
        Assert.Contains("public const string FaxNo = \"Db.Northwind.Customer.Fax No\";", source);
        Assert.Contains("public const string _2Days = \"Db.Northwind.Customer.2Days\";", source);
    }

    [Fact]
    public void Writes_A_Class_That_Has_The_Name_Of_The_Class_It_Is_In_With_An_Underscore()
    {
        // a row that is named after its own module has the same segment twice, e.g. DataAuditLogRow of the module
        // "Pro.DataAuditLog", whose keys are "Db.Pro.DataAuditLog.DataAuditLog.*", and a class can not have the name of
        // the class that it is in
        var result = TextKeysWriter.Write([
            "Db.Pro.DataAuditLog.DataAuditLog.EntityPlural",
            "Db.Pro.DataAuditLog.DataAuditLog.InsertDate"]);
        var source = result.Source.Replace("\r\n", "\n");

        Assert.Contains("public static partial class DataAuditLog\n", source);
        Assert.Contains("public static partial class DataAuditLog_\n", source);
        // the summary names the keys that the class holds, e.g. the one of a row that is named after its own module
        Assert.Contains("The text keys under \"Db.Pro.DataAuditLog.DataAuditLog\"", source);
        Assert.DoesNotContain("The text keys under \"Db.Pro.DataAuditLog.DataAuditLog_\"", source);
        Assert.Contains("public const string EntityPlural = " +
            "\"Db.Pro.DataAuditLog.DataAuditLog.EntityPlural\";", source);
        Assert.Contains("public const string InsertDate = " +
            "\"Db.Pro.DataAuditLog.DataAuditLog.InsertDate\";", source);
        Assert.Empty(result.Diagnostics);
    }

    [Fact]
    public void Keeps_A_Key_That_Differs_Only_In_Case_From_A_Class_With_Its_Own_Name()
    {
        // "Db.fax" is not "Db.Fax", as the keys are case sensitive, so it keeps a name of its own rather than becoming
        // the text of the class of "Db.Fax", which is what a key of the same name would be
        var result = TextKeysWriter.Write(["Db.Fax.Y", "Db.fax"]);
        var source = result.Source.Replace("\r\n", "\n");

        Assert.Contains("public static partial class Fax", source);
        Assert.Contains("public const string Y = \"Db.Fax.Y\";", source);
        Assert.Contains("public const string fax = \"Db.fax\";", source);
        Assert.Empty(result.Diagnostics);
        Assert.DoesNotContain("Not written", source);
    }

    [Fact]
    public void Writes_A_Key_That_Has_The_Name_Of_A_Class_Of_Its_Own_As_The_TextKey_Of_That_Class_Even_When_The_Case_Differs()
    {
        // "Db.Fax.fax" and "Db.Fax.Fax" are both the text of the class of the keys under them, and there is one key of
        // a class, so one of them is the TextKey and the other keeps the name of its own segment
        var result = TextKeysWriter.Write(["Db.Fax.Fax", "Db.Fax.fax"]);
        var source = result.Source.Replace("\r\n", "\n");

        Assert.Contains("public static partial class Fax", source);
        Assert.Contains("public const string TextKey = \"Db.Fax.Fax\";", source);
        Assert.Contains("public const string fax = \"Db.Fax.fax\";", source);
        Assert.Empty(result.Diagnostics);
    }

    [Fact]
    public void Writes_A_Key_That_Has_The_Name_Of_A_Class_As_The_TextKey_Of_That_Class()
    {
        // "Db.Fax" is a key of its own, and the class of the keys "Db.Fax.Y" at the same time, and a constant can not
        // share the name of the class that the keys under it are in
        var result = TextKeysWriter.Write(["Db.Fax", "Db.Fax.Y"]);
        var source = result.Source.Replace("\r\n", "\n");

        Assert.Contains("public static partial class Fax", source);
        Assert.Contains("public const string TextKey = \"Db.Fax\";", source);
        Assert.Contains("public const string Y = \"Db.Fax.Y\";", source);
        Assert.Empty(result.Diagnostics);
        Assert.DoesNotContain("Not written", source);
    }

    [Fact]
    public void Writes_A_Key_Of_A_Class_With_Its_Segment_When_TextKey_Is_Taken()
    {
        // the class has a key of the name TextKey already, so the key of the class itself takes the name of its segment
        var result = TextKeysWriter.Write(["Db.Fax", "Db.Fax.Y", "Db.Fax.TextKey"]);
        var source = result.Source.Replace("\r\n", "\n");

        Assert.Contains("public const string TextKey = \"Db.Fax.TextKey\";", source);
        Assert.Contains("public const string Fax_ = \"Db.Fax\";", source);
        Assert.Contains("public const string Y = \"Db.Fax.Y\";", source);
        Assert.DoesNotContain("TextKey_", source);
        Assert.Empty(result.Diagnostics);
    }

    [Fact]
    public void Writes_A_Key_That_Has_The_Name_Of_Its_Class_As_Its_TextKey()
    {
        // a member can not have the name of the class that it is in either, e.g. "Controls.Dialog.Dialog"
        var source = Write("Controls.Dialog.Dialog", "Controls.Dialog.DialogTitle");

        Assert.Contains("public static partial class Dialog", source);
        Assert.Contains("public const string TextKey = \"Controls.Dialog.Dialog\";", source);
        Assert.Contains("public const string DialogTitle = \"Controls.Dialog.DialogTitle\";", source);
    }

    [Fact]
    public void Writes_A_Page_That_Is_A_Folder_Of_Other_Pages_As_Its_TextKey()
    {
        // the keys of the navigation texts have a key for a page and keys for the pages under it
        var source = Write("Navigation.Basic Samples", "Navigation.Basic Samples/Dialogs",
            "Navigation.Basic Samples/Dialogs/Open");

        Assert.Contains("public static partial class BasicSamples", source);
        Assert.Contains("public const string TextKey = \"Navigation.Basic Samples\";", source);
        Assert.Contains("public static partial class Dialogs", source);
        Assert.Contains("public const string TextKey = \"Navigation.Basic Samples/Dialogs\";", source);
        Assert.Contains("public const string Open = \"Navigation.Basic Samples/Dialogs/Open\";", source);
    }

    [Fact]
    public void Writes_The_Second_Key_Of_A_Class_With_An_Underscore()
    {
        // "Controls.Dialogs" is the key of the class Dialogs, and "Controls.Dialogs.Dialogs" is a key of that class
        // as well, so the one takes TextKey, and the other the name of its segment with an underscore at its end
        var result = TextKeysWriter.Write(["Controls.Dialogs", "Controls.Dialogs.Dialogs"]);
        var source = result.Source.Replace("\r\n", "\n");

        Assert.Contains("public static partial class Dialogs", source);
        Assert.Contains("public const string TextKey = \"Controls.Dialogs\";", source);
        Assert.Contains("public const string Dialogs_ = \"Controls.Dialogs.Dialogs\";", source);
        Assert.Empty(result.Diagnostics);
    }

    [Fact]
    public void Gives_Up_On_A_Key_Of_A_Class_That_Has_No_Name_Left()
    {
        // the keys that have a name of their own take it first, and the key of the class itself is written when a name
        // is free for it, as it is the one that can be read from the others
        var result = TextKeysWriter.Write(["Controls.Dialogs", "Controls.Dialogs.Dialogs", "Controls.Dialogs.Dialogs_"]);
        var source = result.Source.Replace("\r\n", "\n");

        Assert.Contains("public const string TextKey = \"Controls.Dialogs\";", source);
        Assert.Contains("public const string Dialogs_ = \"Controls.Dialogs.Dialogs_\";", source);
        Assert.Contains("//   Controls.Dialogs.Dialogs -> Controls.Dialogs.Dialogs_", source);

        var diagnostic = Assert.Single(result.Diagnostics);
        Assert.Equal(TextKeyDiagnostic.NameTaken, diagnostic.Id);
        Assert.Contains("Controls.Dialogs.Dialogs", diagnostic.Message);
    }

    [Fact]
    public void Writes_The_TextKey_Of_A_Class_Once_And_In_That_Class()
    {
        // the keys of the navigation texts of an application are a page and the pages under it, at more than one level
        var source = Write(
            "Navigation.Basic Samples",
            "Navigation.Basic Samples/Dialogs",
            "Navigation.Basic Samples/Dialogs/Open",
            "Navigation.Basic Samples/Editors",
            "Navigation.Basic Samples/Editors/Filtered");

        Assert.Equal(3, source.Split("public const string TextKey =").Length - 1);
        Assert.Contains("public static partial class BasicSamples", source);
        Assert.Contains("public static partial class Dialogs", source);
        Assert.Contains("public static partial class Editors", source);

        // each of them is in its own class, and not in the one that it is read from as well
        var navigation = source[source.IndexOf("class Navigation")..];
        Assert.Contains("TextKey = \"Navigation.Basic Samples\"", navigation);
        Assert.DoesNotContain("TextKey = \"Navigation.Basic Samples/Dialogs\"",
            navigation[..navigation.IndexOf("class Dialogs")]);
    }

    [Fact]
    public void Splits_A_Key_On_The_Slashes_Of_Its_Path_Segments_As_Well_As_On_Its_Dots()
    {
        // the keys of the navigation texts of an application have the path of their page as segments, e.g.
        // "Navigation.Basic Samples/Editors/Filtered Lookup in Detail"
        var source = Write(
            "Navigation.Basic Samples/Editors/Filtered Lookup in Detail",
            "Navigation.Basic Samples/Editors/Orders");

        Assert.Contains("public static partial class Navigation", source);
        Assert.Contains("public static partial class BasicSamples", source);
        Assert.Contains("public static partial class Editors", source);
        Assert.Contains("public const string FilteredLookupInDetail = " +
            "\"Navigation.Basic Samples/Editors/Filtered Lookup in Detail\";", source);
        // the key keeps the slashes and the spaces that it has, only its name is normalized
        Assert.DoesNotContain("public static partial class Basic Samples", source);
    }

    [Fact]
    public void Reads_Two_Slashes_Of_A_Path_As_A_Slash_That_Is_A_Part_Of_The_Segment()
    {
        // a folder that has a slash in its name is written with two of them in the key of the page in it
        var source = Write("Navigation.A//B/C");
        Assert.Contains("public static partial class AB", source);
        Assert.Contains("public const string C = \"Navigation.A//B/C\";", source);
        Assert.Contains("The text keys under \"Navigation.AB\"", source);
    }

    [Fact]
    public void Drops_The_Empty_Segments_Of_A_Path()
    {
        var source = Write("Navigation./A/");
        Assert.Contains("public static partial class Navigation", source);
        Assert.Contains("public const string A = \"Navigation./A/\";", source);
    }

    [Fact]
    public void Keeps_A_Slash_Of_A_Key_That_Is_Not_A_Navigation_Path()
    {
        // the slashes of a key are the separators of the path of a page in the keys of the navigation texts only
        var source = Write("Db.Northwind.A/B");
        Assert.Contains("public const string AB = \"Db.Northwind.A/B\";", source);
        Assert.DoesNotContain("public static partial class A ", source);
    }

    [Fact]
    public void Keeps_A_Dot_Of_A_Path_As_A_Part_Of_Its_Segment()
    {
        // after the first slash of a key, a dot is a part of the segment and not a separator, and is removed like the
        // other characters that an identifier can not have
        var source = Write("Navigation.Admin/Reports/Orders.List");
        Assert.Contains("public static partial class Navigation", source);
        Assert.Contains("public static partial class Admin", source);
        Assert.Contains("public static partial class Reports", source);
        Assert.Contains("public const string OrdersList = \"Navigation.Admin/Reports/Orders.List\";", source);
    }

    [Fact]
    public void Skips_A_Key_That_Has_No_Identifier_For_One_Of_Its_Segments()
    {
        var result = TextKeysWriter.Write(["Db.A.+++", "Db.B.Value"]);
        Assert.Contains("public const string Value = \"Db.B.Value\";", result.Source);

        var diagnostic = Assert.Single(result.Diagnostics);
        Assert.Equal(TextKeyDiagnostic.UnmapableSegment, diagnostic.Id);
        Assert.Contains("Db.A.+++", diagnostic.Message);
    }

    [Fact]
    public void Writes_A_Key_Once_When_It_Is_Asked_For_Twice()
    {
        // the same key twice is the same text, so it is written once and nothing is said about it
        var result = TextKeysWriter.Write(["Db.Northwind.Customer.Fax", "Db.Northwind.Customer.Fax"]);
        Assert.Equal(1, result.Source.Split("public const string Fax =").Length - 1);
        Assert.Empty(result.Diagnostics);
        Assert.DoesNotContain("Not written", result.Source);
    }

    [Fact]
    public void Escapes_The_Quotes_And_The_Backslashes_Of_A_Key()
    {
        var source = Write("Db.A.B\"C\\D");
        Assert.Contains("public const string BCD = \"Db.A.B\\\"C\\\\D\";", source);
    }

    [Fact]
    public void Escapes_A_Text_That_The_Docs_Need_It_In()
    {
        var source = TextKeysWriter.Write(["Db.A.B"], texts: new Dictionary<string, string?>
        {
            ["Db.A.B"] = "A & <B>"
        }).Source;

        Assert.Contains("/// <summary>A &amp; &lt;B&gt;</summary>", source);
    }

    [Fact]
    public void Skips_A_Key_That_Can_Not_Keep_A_Name_Of_Its_Own()
    {
        // "x y" and "x-y" are mangled to the same identifier, which the key "xy" has as it is, so one of them takes
        // the name of its own segment, and the other one has no name left
        var result = TextKeysWriter.Write(["Db.A.x y", "Db.A.x-y", "Db.A.xy"]);
        var source = result.Source.Replace("\r\n", "\n");

        Assert.Contains("public const string Xy = \"Db.A.xy\";", source);
        Assert.Contains("public const string XY = \"Db.A.x y\";", source);
        Assert.Contains("//   Db.A.x-y -> Db.A.x y", source);
        Assert.DoesNotContain("\"Db.A.x-y\";", source);

        var diagnostic = Assert.Single(result.Diagnostics);
        Assert.Equal(TextKeyDiagnostic.NameTaken, diagnostic.Id);
        Assert.Contains("Db.A.x-y", diagnostic.Message);
    }
}
